import { ProjectTemplate } from '../../schemas/templateSchemas';

/**
 * Everyday IT project templates (2026-10-15): the projects a small IT team or consultant runs
 * most — apps and websites, software selection, reporting, security readiness, training,
 * Dynamics and Microsoft 365 migrations, servers, backups, devices, networks, offices, CRM and
 * AI pilots.
 *
 * Same standard as the templates in TemplateService.ts: links sit on tasks, never on phases;
 * every task leads to a later one or to the closing milestone; milestones are zero-day
 * outcomes named for what becomes true; no single task runs past the review's long-task limit
 * for its project type; and each template's length is its critical path laid out from a Monday.
 * builtInTemplatesReview.test.ts runs Kovarti's own Schedule Review over every one of them.
 * Starter RAID items for each live in starterRaid.ts, keyed by id.
 */

